import ast
import os
import sys
import subprocess
import tempfile
import shutil
import re
import time
import tomllib
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module if available, otherwise define fallbacks
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        filter_bundle,
        partition_bundle,
        count_source_files
    )
except ImportError:
    # Fallback definitions if artifacts.py is not yet available or import fails
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if '*' in path or '`' in path:
            return True
        if path != path.strip():
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Tuple[str, ...] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if path.endswith(suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = len([g for g in evaluated if g.passed])
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "PASS" if g.passed else ("SKIP" if g.status == SKIPPED else "FAIL")
            lines.append(f"[{status_icon}] {g.name}: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional path hint
    # Matches: ```python\n...``` or ```path/to/file.py\n...```
    # We look for blocks where the info string might contain a path ending in .py
    pattern = r"```(?:python|py|path)?\s*([^\n]*)\n(.*?)```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for info, content in matches:
        # Try to extract a path from the info string
        # Common patterns: "path/to/file.py", "file.py", "python path/to/file.py"
        path_match = re.search(r"([a-zA-Z0-9_\-/\.]+\.py)", info)
        if path_match:
            path = path_match.group(1)
            # Clean up path
            path = path.strip()
            if path and not is_malformed_path(path):
                bundle[path] = content
        else:
            # If no path in info, we can't reliably map it. 
            # Some agents might put the path in the first line of the code block?
            # Or we might just skip it if we can't determine the path.
            # The spec says "Recovers a path->content map". If we can't find a path, we can't map it.
            pass

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
            elif isinstance(workspace, dict):
                bundle = workspace
            elif hasattr(workspace, 'files'):
                bundle = workspace.files

        # If bundle is empty, try extracting from deliverable text
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata_check', detail='No packaging metadata found'),
            GateResult(name='smoke', status=FAILED, method='import_check', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest_run', detail='No tests found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No Python files to analyze'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=5 * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        python_files = count_source_files(authored_bundle, ('.py',))
        authored_files = len(authored_bundle)

        if python_files == 0:
            return self._create_empty_report(source)

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write bundle to disk
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            bundle = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                bundle[rel_path] = f.read()
                        except Exception:
                            pass
            authored = bundle

        python_files = count_source_files(authored, ('.py',))
        authored_files = len(authored)

        if python_files == 0:
            return self._create_empty_report(source)

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in bundle if p.endswith('.py')]
        if not py_files:
            return GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files', duration_s=time.time()-start)

        errors = []
        for path in py_files:
            content = bundle[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast_parse', detail='; '.join(errors), duration_s=duration)
        return GateResult(name='syntax', status=PASSED, method='ast_parse', detail='All Python files parsed successfully', duration_s=duration)

    def _gate_build(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for metadata files
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None
        for mf in metadata_files:
            if mf in bundle:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(name='build', status=FAILED, method='metadata_check', detail='No packaging metadata found', duration_s=time.time()-start)

        # If pyproject.toml, validate it
        if found_metadata == 'pyproject.toml':
            content = bundle['pyproject.toml']
            try:
                data = tomllib.loads(content)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(name='build', status=FAILED, method='toml_validation', detail='pyproject.toml missing required tables', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='toml_validation', detail=f'Invalid pyproject.toml: {e}', duration_s=time.time()-start)

        # Try to install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], check=True, capture_output=True, timeout=10)
        except Exception:
            return GateResult(name='build', status=SKIPPED, method='pip_install', detail='pip not available', duration_s=time.time()-start)

        try:
            # Run pip install -e . --no-deps --no-build-isolation
            # We need to run this in the workdir
            cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
            subprocess.run(cmd, cwd=workdir, check=True, capture_output=True, timeout=self.timeout_s)
            duration = time.time() - start
            return GateResult(name='build', status=PASSED, method='pip_install', detail='Package installed successfully', duration_s=duration)
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method='pip_install', detail='Installation timed out', duration_s=time.time()-start)
        except subprocess.CalledProcessError as e:
            stderr = e.stderr.decode('utf-8', errors='ignore') if e.stderr else ''
            return GateResult(name='build', status=FAILED, method='pip_install', detail=f'Installation failed: {stderr}', duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name='build', status=FAILED, method='pip_install', detail=f'Installation error: {e}', duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test modules
        # Exclude test files
        modules = []
        for path in bundle:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            # Convert path to module name
            # Remove .py
            mod_path = path[:-3]
            # Replace / with .
            mod_name = mod_path.replace('/', '.').replace('\\', '.')
            # Handle __init__.py
            if mod_name.endswith('.__init__'):
                mod_name = mod_name[:-9]
            if mod_name:
                modules.append(mod_name)

        if not modules:
            return GateResult(name='smoke', status=FAILED, method='import_check', detail='No importable modules found', duration_s=time.time()-start)

        # Prepare environment
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = f"{python_path}:{env['PYTHONPATH']}"
        else:
            env['PYTHONPATH'] = python_path

        # Try importing each module in a subprocess
        failed_modules = []
        skipped_modules = []

        for mod_name in modules:
            code = f"import {mod_name}"
            try:
                subprocess.run([self.python_executable, '-c', code], cwd=workdir, env=env, check=True, capture_output=True, timeout=10)
            except subprocess.CalledProcessError as e:
                stderr = e.stderr.decode('utf-8', errors='ignore') if e.stderr else ''
                if 'ModuleNotFoundError' in stderr:
                    # Check if it's a third-party package
                    # If the module itself is not found, it's a failure.
                    # If a dependency is not found, it's skipped.
                    # This is tricky. If `import mod_name` fails with ModuleNotFoundError, 
                    # it could be mod_name itself or a dependency.
                    # If mod_name is in our bundle, it should be found.
                    # If it's a dependency, we skip.
                    # We assume if the error mentions the module name itself, it's a failure.
                    # Otherwise, it's likely a dependency issue.
                    if f"No module named '{mod_name}'" in stderr or f"No module named \"{mod_name}\"" in stderr:
                        failed_modules.append(mod_name)
                    else:
                        skipped_modules.append(mod_name)
                else:
                    failed_modules.append(mod_name)
            except Exception:
                failed_modules.append(mod_name)

        duration = time.time() - start

        if failed_modules:
            return GateResult(name='smoke', status=FAILED, method='import_check', detail=f'Failed to import: {", ".join(failed_modules)}', duration_s=duration)

        if skipped_modules and not failed_modules:
            # If all modules were skipped due to missing deps, return SKIPPED
            if len(skipped_modules) == len(modules):
                return GateResult(name='smoke', status=SKIPPED, method='import_check', detail='All modules skipped due to missing dependencies', duration_s=duration)
            # If some passed and some skipped, it's a pass? 
            # Spec: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
            # This implies if ANY module fails with ModuleNotFoundError (even if others pass), we might need to be careful.
            # But usually, if we can import some, the workspace is "smokeable".
            # Let's interpret "fail solely" as "the gate cannot be evaluated because of missing deps".
            # If we have a mix, we probably PASSED the ones we could.
            # However, if a core module fails, it's bad.
            # Let's stick to: if any module fails with a non-ModuleNotFoundError error, it's FAILED.
            # If all modules either pass or fail with ModuleNotFoundError (deps), then SKIPPED.
            # But if some pass, is it PASSED?
            # "If no importable modules exist or any module fails with a syntax or runtime error, return FAILED."
            # "If module imports fail solely with ModuleNotFoundError... return SKIPPED"
            # This suggests if we have a mix of Pass and Skip, it's not "solely" failing with ModuleNotFoundError.
            # But if we have Pass and Fail (syntax), it's Fail.
            # If we have Pass and Skip (deps), it's ambiguous.
            # Let's assume if we successfully imported at least one, and none failed with syntax/runtime, it's PASSED.
            # But if we couldn't import any because of deps, it's SKIPPED.
            if len(skipped_modules) < len(modules):
                 # Some passed, some skipped.
                 return GateResult(name='smoke', status=PASSED, method='import_check', detail=f'Imported {len(modules)-len(skipped_modules)} modules, skipped {len(skipped_modules)} due to deps', duration_s=duration)
            else:
                 return GateResult(name='smoke', status=SKIPPED, method='import_check', detail='All modules skipped due to missing dependencies', duration_s=duration)

        return GateResult(name='smoke', status=PASSED, method='import_check', detail='All modules imported successfully', duration_s=duration)

    def _gate_tests(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find test files
        test_files = [p for p in bundle if 'test' in os.path.basename(p).lower() and p.endswith('.py')]

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='pytest_run', detail='No test files found', duration_s=time.time()-start)

        # Prepare environment
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = f"{python_path}:{env['PYTHONPATH']}"
        else:
            env['PYTHONPATH'] = python_path

        # Check if pytest is installed
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], check=True, capture_output=True, timeout=10)
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            try:
                # Run pytest on the test files
                # We need to pass the test files explicitly or let pytest discover them
                # Let's run pytest on the workdir
                cmd = [self.python_executable, '-m', 'pytest', '-v', '--tb=short']
                # Add test files to command to ensure they are run
                for tf in test_files:
                    cmd.append(tf)

                result = subprocess.run(cmd, cwd=workdir, env=env, capture_output=True, timeout=self.timeout_s)
                duration = time.time() - start

                if result.returncode == 0:
                    return GateResult(name='tests', status=PASSED, method='pytest_run', detail='All tests passed', duration_s=duration)
                else:
                    stderr = result.stderr.decode('utf-8', errors='ignore') if result.stderr else ''
                    stdout = result.stdout.decode('utf-8', errors='ignore') if result.stdout else ''
                    # Check for ModuleNotFoundError in output
                    if 'ModuleNotFoundError' in stderr or 'ModuleNotFoundError' in stdout:
                        # Check if it's a test collection error or a runtime error
                        # If tests were collected but failed due to import, it might be skipped?
                        # Spec: "If 0 tests are collected because of ModuleNotFoundError... return SKIPPED"
                        # If tests ran and failed, it's FAILED.
                        # If pytest exits with code 5 (no tests collected), and error is ModuleNotFoundError, it's SKIPPED.
                        if result.returncode == 5:
                            return GateResult(name='tests', status=SKIPPED, method='pytest_run', detail='No tests collected due to missing dependencies', duration_s=duration)

                    return GateResult(name='tests', status=FAILED, method='pytest_run', detail=f'Tests failed: {stderr[:500]}', duration_s=duration)
            except subprocess.TimeoutExpired:
                return GateResult(name='tests', status=FAILED, method='pytest_run', detail='Tests timed out', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='tests', status=FAILED, method='pytest_run', detail=f'Pytest execution error: {e}', duration_s=time.time()-start)
        else:
            # Stdlib fallback
            # Run a script that imports each test file and collects/executes tests
            # This is complex. We'll write a temporary script.

            script_content = """
import sys
import os
import unittest
import importlib.util

def run_tests(test_files):
    loader = unittest.TestLoader()
    suite = unittest.TestSuite()

    for tf in test_files:
        try:
            # Load module
            spec = importlib.util.spec_from_file_location("test_module", tf)
            if spec is None:
                continue
            module = importlib.util.module_from_spec(spec)
            sys.modules["test_module"] = module
            spec.loader.exec_module(module)

            # Collect unittest.TestCase subclasses
            for name in dir(module):
                obj = getattr(module, name)
                if isinstance(obj, type) and issubclass(obj, unittest.TestCase) and obj.__module__ == module.__name__:
                    suite.addTests(loader.loadTestsFromTestCase(obj))

            # Collect bare test_* functions
            for name in dir(module):
                if name.startswith('test_'):
                    obj = getattr(module, name)
                    if callable(obj) and not isinstance(obj, type):
                        # Check if it takes 0 required args
                        import inspect
                        sig = inspect.signature(obj)
                        params = sig.parameters
                        # Allow self if it's a method? No, bare functions.
                        # If it has required args, skip.
                        has_required = False
                        for p in params.values():
                            if p.default is inspect.Parameter.empty and p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD, inspect.Parameter.KEYWORD_ONLY):
                                has_required = True
                                break
                        if not has_required:
                            # Wrap in a TestCase
                            class TestWrapper(unittest.TestCase):
                                def test_wrapper(self):
                                    obj()
                            TestWrapper.__name__ = f"Test_{name}"
                            suite.addTests(loader.loadTestsFromTestCase(TestWrapper))
        except ModuleNotFoundError as e:
            print(f"ModuleNotFoundError: {e}", file=sys.stderr)
            sys.exit(2) # Signal skip
        except Exception as e:
            print(f"Error loading {tf}: {e}", file=sys.stderr)
            sys.exit(1) # Signal fail

    if suite.countTestCases() == 0:
        print("No tests collected", file=sys.stderr)
        sys.exit(0) # Success? Or fail? Spec says "If 0 tests are collected... return SKIPPED" if due to ModuleNotFoundError.
                     # If 0 tests collected for other reasons, it's likely FAILED.
